    <p class="ws-meta" id="dashboard-freshness">Updated {{ $as_of }} · refreshes every 30 seconds</p>
    <script>
    setInterval(async () => {
        if (document.hidden) return;
        try {
            const response = await fetch(@json(route('workspace.home', ['context' => $context['id']])), {headers: {'Accept':'application/json'}, cache:'no-store'});
            if (!response.ok) { if ([401,403].includes(response.status)) location.reload(); return; }
            const data = await response.json();
            data.summary.forEach((stat, i) => { const node = document.querySelector('[data-summary-index="'+i+'"]'); if(node) node.textContent = new Intl.NumberFormat().format(stat.value); });
            document.getElementById('dashboard-freshness').textContent = 'Updated ' + data.as_of + ' · refreshes every 30 seconds';
        } catch (_) {}
    }, 30000);
    </script>
